local function BucketKey(key)
    local length = #key
    if length >= 2 then return key:sub(1, 2) end
    if length == 1 then return key .. "_" end
    return "__"
end

function I.Lookup(deleteKey, output, ordered, maximum)
    if deleteKey == nil then return 0 end
    local blob = I.buckets[BucketKey(deleteKey)]
    if not blob then return 0 end
    local needle = "\n" .. deleteKey .. "\t"
    local _, valueStart = string.find(blob, needle, 1, true)
    if not valueStart then return 0 end
    local lineEnd = string.find(blob, "\n", valueStart + 1, true) or (#blob + 1)
    local list = string.sub(blob, valueStart + 1, lineEnd - 1)
    local added = 0
    for word in string.gmatch(list, "[^,]+") do
        if not output[word] then
            output[word] = true
            added = added + 1
            if ordered then ordered[#ordered + 1] = word end
            if maximum and added >= maximum then break end
        end
    end
    return added
end

return I
